TLM.f("Tempora/Pent07-4",{"officium":"Feria quinta infra Hebdomadam VII post Octavam Pentecostes","rule":["Oratio Dominica","Suffr=Sanctorum;Maria3,Ecclesiæ,Papa;;"],"ruleInherited":["Gloria","Credo","Prefatio=Trinitate","Suffr=Sanctorum;Maria3,Ecclesiæ,Papa;;"],"fallback":"Tempora/Pent07-0","from":{"Introitus":"Tempora/Pent07-0","Oratio":"Tempora/Pent07-0","Lectio":"Tempora/Pent07-0","Graduale":"Tempora/Pent07-0","Evangelium":"Tempora/Pent07-0","Offertorium":"Tempora/Pent07-0","Secreta":"Tempora/Pent07-0","Communio":"Tempora/Pent07-0","Postcommunio":"Tempora/Pent07-0"},"sections":{"Introitus":[{"k":"ref","la":"Ps 46:2"},{"k":"text","la":"Omnes gentes, pláudite mánibus: jubiláte Deo in voce exsultatiónis."},{"k":"ref","la":"Ps 46:3"},{"k":"text","la":"Quóniam Dóminus excélsus, terríbilis: Rex magnus super omnem terram."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Omnes gentes, pláudite mánibus: jubiláte Deo in voce exsultatiónis."}],"Oratio":[{"k":"text","la":"Deus, cujus providéntia in sui dispositióne non fállitur: te súpplices exorámus; ut nóxia cuncta submóveas, et ómnia nobis profutúra concédas."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Romános"},{"k":"ref","la":"Rom 6:19-23"},{"k":"text","la":"Fratres: Humánum dico, propter infirmitátem carnis vestræ: sicut enim exhibuístis membra vestra servíre immundítiæ et iniquitáti ad iniquitátem, ita nunc exhibéte membra vestra servíre justítiæ in sanctificatiónem. Cum enim servi essétis peccáti, líberi fuístis justítiæ. Quem ergo fructum habuístis tunc in illis, in quibus nunc erubéscitis? Nam finis illórum mors est. Nunc vero liberáti a peccáto, servi autem facti Deo, habétis fructum vestrum in sanctificatiónem, finem vero vitam ætérnam. Stipéndia enim peccáti mors. Grátia autem Dei vita ætérna, in Christo Jesu, Dómino nostro."}],"Graduale":[{"k":"ref","la":"Ps 33:12; 33:6"},{"k":"text","la":"Veníte, fílii, audíte me: timórem Dómini docébo vos."},{"k":"text","la":"Accédite ad eum, et illuminámini: et fácies vestræ non confundéntur.","mark":"V"},{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps 46:2"},{"k":"text","la":"Omnes gentes, pláudite mánibus: jubiláte Deo in voce exsultatiónis. Allelúja."}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Matthǽum"},{"k":"ref","la":"Matt 7:15-21"},{"k":"text","la":"In illo témpore: Dixit Jesus discípulis suis: Atténdite a falsis prophétis, qui véniunt ad vos in vestiméntis óvium, intrínsecus autem sunt lupi rapáces: a frúctibus eórum cognoscétis eos. Numquid cólligunt de spinis uvas, aut de tríbulis ficus? Sic omnis arbor bona fructus bonos facit: mala autem arbor malos fructus facit. Non potest arbor bona malos fructus fácere: neque arbor mala bonos fructus fácere. Omnis arbor, quæ non facit fructum bonum, excidétur et in ignem mittétur. Igitur ex frúctibus eórum cognoscétis eos. Non omnis, qui dicit mihi, Dómine, Dómine, intrábit in regnum cœlórum: sed qui facit voluntátem Patris mei, qui in cœlis est, ipse intrábit in regnum cœlórum."}],"Offertorium":[{"k":"ref","la":"Dan 3:40"},{"k":"text","la":"Sicut in holocáustis aríetum et taurórum, et sicut in mílibus agnórum pínguium: sic fiat sacrifícium nostrum in conspéctu tuo hódie, ut pláceat tibi: quia non est confúsio confidéntibus in te, Dómine."}],"Secreta":[{"k":"text","la":"Deus, qui legálium differéntiam hostiárum unius sacrifícii perfectione sanxísti: accipe sacrifícium a devótis tibi fámulis, et pari benedictióne, sicut múnera Abel, sanctífica; ut, quod sínguli obtulérunt ad majestátis tuæ honórem, cunctis profíciat ad salútem."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Ps 30:3"},{"k":"text","la":"Inclína aurem tuam, accélera, ut erípias me."}],"Postcommunio":[{"k":"text","la":"Tua nos, Dómine, medicinális operátio, et a nostris perversitátibus cleménter expédiat, et ad ea, quæ sunt recta, perdúcat."},{"k":"macro","name":"Per Dominum"}]},"hr":{"72cbd243eb8d9ba9":{"t":"Ps 46, 2, Ps 46, 3\n(Ps 46, 2) Svi narodi, plješćite rukama, kličite Bogu radosnim glasom. (Ps 46, 3) Jer je Gospodin uzvišen i strašan kralj nad svom zemljom.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 46, 2) Svi narodi, plješćite rukama, kličite Bogu radosnim glasom.","kn":"(Ps. 46, 2). Svi narodi plještite rukama, slavite Boga glasno kličući. (Ps. 46, 3) Jer Gospodin je uzvišen i strašan, kralj velik po svoj zemlji. Slava Ocu . . . Svi narodi . . .","knRef":"Kniewald 1942, str. 382–383 (snimka 192) (OCR)"},"492f4636863a0f10":{"t":"<i>Pomolimo se</i>.\nBože, tvoja je providnost u svojim odredbama pouzdana, pa te ponizno molimo da ukloniš što nam je štetno, a dadeš sve što nam je korisno.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Bože, kojega se promisao u svojem upravljanju ne vara, Tebe prikloniti molimo, da sve štetno ukloniš i sve, što će nam biti za korist, pokloniš, po G. n.","knRef":"Kniewald 1942, str. 384–385 (snimka 193) (OCR)"},"a223120f55ef78ca":{"t":"Rim 6, 19-23\nČitanje Poslanice bl. Pavla apostola Rimljanima. Braćo, govorim vam ljudskim načinom zbog slabosti vašega tijela. Kao što ste nekoć svoje udove dali da služe nečistoći i nepravdi da udovoljite požudi, tako sada predajte svoje udove da služe pravdi na vaše posvećenje. Dok ste robovali grijehu, bili ste daleko od pravde. Pa kakav ste plod imali od onoga čega se sada stidite? Svršetak je toga smrt. Sada, slobodni od grijeha, postali ste Božjim slugama te imate kao svoj plod posvećenje, a kao svršetak vječni život. Plaća je za grijeh smrt, a dar je milosti Božje vječni život u našem Gospodinu Isusu Kristu.","kn":"Čitanje poslanice bi. Pavla apostola Rimljanima (6, 19-23). Braćo! Govorim vam kao čovjek radi sdaboflti vašega tijela, da kao što ste (nekad) svoje udove dali, da robuju nečistoći i nepravdi na bezakonje, tako sada dajte svoje udove, da služe pravdi na posvetu. Vi ste bili daleko od pravde, dok ste robovali grijehu. Kakav ste dakle imali plod od onih stvari, kojih se sada stidite? Jer je smrt njihov svršetak. Kad ste se sada oslobodili grijeha i postali Božjim slugama, kao svoj plod imate posvetu, a svršetak vječni život. Jer smrt je plaća za grijeh, a milost Božja je vječni život u Isusu Kristu, Gospodinu našemu.","knRef":"Kniewald 1942, str. 384–385 (snimka 193) (OCR)"},"c8436e1635065969":{"t":"Ps 33, 12 i 6\nDođite, sinovi, čujte me! Naučit ću vas strahu Gospodnjemu. Pristupite k njemu da se razveselite i da se vaša lica ne zacrvene.\n\nPs 46, 2\n<i>Aleluja</i>, <i>aleluja</i>.\nSvi narodi, plješćite rukama, kličite Bogu radosnim glasom. <i>Aleluja</i>.","kn":"(Ps. 33, 12, 6). Dođite, sinci, poslušajte me; naučit ću vas štovanju Gospodina. Pristupite k njemu i prosvijetlite se, i lice se vaše ne će zastidjeti.\n\nAleluja, aleluja. (Ps. 46, 2) Svi narodi plještite rukama, slavite Boga glasno kličući, <i>aleluja</i>.","knRef":"Kniewald 1942, str. 384–385 (snimka 193) (OCR)"},"9f696b9a49abcf00":{"t":"Mt 7, 15-21\nSlijedi sveto Evanđelje po Mateju. U ono vrijeme reče Isus svojim učenicima: Čuvajte se lažnih proroka koji k vama dolaze u ovčjem runu, a unutra su grabežljivi vuci. Prepoznat ćete ih po njihovim plodovima. Zar se grožđe bere s trnja ili smokve s drače? Tako svako dobro stablo rađa dobrim plodom, a loše stablo slabim plodom. Ne može dobro stablo rađati loših plodova ni slabo stablo dobrih plodova. Svako stablo, koje ne rađa dobra ploda, siječe se i baca u oganj. Dakle, prepoznat ćete ih po njihovim plodovima. U nebesko kraljevstvo neće ući svaki onaj koji mi govori: Gospodine, Gospodine!, nego će u nebesko kraljevstvo ući onaj koji vrši volju mojeg nebeskog Oca.","kn":"t Slijedi sveto evanđelje po Mateju (7, 15-21). U ono vrijeme reče Isus svojim učenicima; Čuvajte se lažnih proroka, koji k vama dolaze u ovčjem odijelu, a iznutra su grabežljivi vuci. Poznat ćete ih po njihovim plodovima. Da li se grožđe bere s trnja ili smokve s bodljike? Tako svako plemenito stablo rađa dobre plodove, a zlo stablo rađa zle plodove. Ne može plemenito stablo rađati zlih plodova, niti zlo stablo dobrih plodova. Svako stablo, koje ne rađa dobra ploda, posjeći će se i baciti U oganj.: Ne će uči u kraljevstvo nebesko svaki onaj, koji mi govori: Gospodine, Gospodine! Nego će onaj ući u kraljevstvo nebesko, koji vrši volju moga nebeskog Oca.","knRef":"Kniewald 1942, str. 384–385 (snimka 193) (OCR)"},"934020c33ae3c84c":{"t":"Dn 3, 40\nKao kad bismo prinijeli žrtve paljenice ovnova i bikova i tisuće pretilih jaganjaca, tako neka se svidi tvojemu pogledu naša žrtva, jer se neće posramiti oni koji se uzdaju u tebe, Gospodine.","kn":"(Dan. 3, 40), .Kao. u paljenicama jaraca i bikova i kao u tisućama pretilih jaganjaca, tako da. je žrtva naša danas pred Tobom, da Ti ugodi; jer se ne će postidjeti, koji se u Tebe uzdaju. Gospodine.","knRef":"Kniewald 1942, str. 384–385 (snimka 193) (OCR)"},"4344285f9f006854":{"t":"Bože, koji si raznovrsne starozavjetne žrtve potvrdio po savršenstvu jedine žrtve, primi žrtvu od odanih ti slugu i posveti je istim blagoslovom kao žrtvu Abelovu, da bude na spasenje svima ono što pojedinci prikazaše na čast tvoga veličanstva.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Bože, koji si različnost zakonskih . žrtavd p.osvetio savršenošću. jedne .žrtve, primi .žrtvu od pobožniih .slugu svojih i posveti . jednakim bragoslovoni, kao. i darove Abeloye, .te što pojedinci prikazaše ng. čast veličanstva *.Tvojega,^ da svima uskoristi za. spasenje, po G. n. ' . , . i Predslo, vi je presvetog Trojstva.","knRef":"Kniewald 1942, str. 384–385 (snimka 193) (OCR)"},"404159d2e4df1ef4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:","kn":"Predslovlje. Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti, Oče svemogući, vjećni Bože, po Kristu, Gospodinu našemu, po kome veličanstvo Tvoje hvale anđeli, klanjaju Ti se gospodstva, tresu se vlasti. Nebesa Te i nebeske moći i . blaženi Serafini zadružnim klicanjem zajedno slave. Zapovjedi, molimo, da se i naši glasovi združe s njihovima, smjernim ispovijedanjem govoreći:","knRef":"Kniewald 1942, str. 758–759 (snimka 380) (OCR)"},"f68a9f5797194a0f":{"t":"Ps 30, 3\nPrikloni svoje uho, pohiti da me izbaviš.","kn":"(Ps. 30, 1). Prigni uho svoje, pohiti da me izbaviš.. , .,<■ .","knRef":"Kniewald 1942, str. 384–385 (snimka 193) (OCR)"},"4e7e3a8170db91f7":{"t":"<i>Pomolimo se</i>.\nTvoje spasonosno djelovanje, Gospodine, neka nas dobrostivo izbavi od naših opačina i privede k onomu što je pravedno.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Tvoje nam Gospodine, spasoinos, no djelovanje milostivo oprostilo naše, opačine, i k onomu, što je pravo, dovelo, po. G. n; ..- ...","knRef":"Kniewald 1942, str. 384–385 (snimka 193) (OCR)"}}});
